class Flower {
	constructor(x, y, r) {
		this.pos = createVector(x, y)
		this.r = r;
		this.d = random(0.2)
		this.topNum = int(random(10))
		this.angle = random(360);

	}
	show() {
		push();
		fill(255, 0)
		noStroke();
		translate(this.pos.x, this.pos.y)
		rotate(this.angle)

		beginShape();
		for (let i = 0; i < 360; i += 1) {
			let radius = this.r + ((this.r * this.d) * Math.sin(i * this.topNum));
			let ex = radius * Math.sin(i);
			let ey = radius * Math.cos(i);
			vertex(ex, ey)
		}
		endShape(CLOSE)

		drawingContext.clip()

		push();
		let nums = 280
		let w = width / nums;
		noStroke();
		fill(random(palette_selected))
		translate(-width / 2, -height / 2)
		for (let j = 0; j < nums; j++) {
			for (let i = 0; i < nums; i++) {
				if (j % 2) {
					ellipse(i * w + w / 2, j * w, w * 0.5)
				} else {
					ellipse(i * w, j * w, w * 0.5)
				}
			}
		}
		pop();
		pop();
	}
}
class Poly {
	constructor(x, y, r) {
		this.pos = createVector(x, y)
		this.r = r;
		this.angle = random(360);
		this.d = r * random(0.3, 0.8)
		this.col1 = color(random(paletteSelected1));
		this.col1.setAlpha(10)
		this.col2 = color(random(paletteSelected2));

	}
	show() {

		push();

		translate(this.pos.x, this.pos.y)
		rotate(this.angle)
		if (random() < 0.9) {
			noStroke();
			let gradientFill = drawingContext.createLinearGradient(
				0,
				-this.d,
				0,
				this.d
			);
			gradientFill.addColorStop(0, color(this.col1));
			gradientFill.addColorStop(1, color(this.col2));
			drawingContext.fillStyle = gradientFill;
		} else {
			noFill();
			stroke(paletteSelected1)
		}

		if (random() < 0.5) {
			beginShape();
			let nums = int(random(3, 6))
			let dep = random(0.1, 0.3)
			for (let i = 0; i < 360; i += 1) {
				let radius = this.d + (this.d * dep * sin(i * nums));
				let ex = radius * sin(i);
				let ey = radius * cos(i);
				vertex(ex, ey)
			}
			endShape(CLOSE)
		} else {
			let h = this.d * random(0.2, 1)
			rect(0, 0, this.d, h, abs(h / 2))
		}

		pop();
	}
}

function grid() {
	let g_num = 60; //罫
	let w = width / g_num;
	strokeWeight(0.5)
	for (let x = 0; x < g_num; x++) {
		for (let y = 0; y < g_num; y++) {
			stroke(random(palette_selected));

			if (x % 2 || y % 2) {
				push();
				drawingContext.setLineDash([1, 2]);
				line(x * w, 0, x * w, height);
				line(0, y * w, width, y * w);
				pop();
			} else {
				line(x * w, 0, x * w, height)
				line(0, y * w, width, y * w);
			}
		}
	}
}

